// Writes text to the pasteboard, optionally marked the way password managers
// mark it (nspasteboard.org). Used by scripts/probe-e2e.sh.
// Usage: pasteboard-write <text> [concealed|transient|autogenerated]
import AppKit
let args = CommandLine.arguments
let pb = NSPasteboard.general
pb.clearContents()
pb.setString(args[1], forType: .string)
if args.count > 2 {
    let marker = ["concealed": "org.nspasteboard.ConcealedType", "transient": "org.nspasteboard.TransientType",
                  "autogenerated": "org.nspasteboard.AutoGeneratedType"][args[2]]!
    pb.setData(Data(), forType: NSPasteboard.PasteboardType(marker))
}
